const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define date and geometries
    const targetDate = '2018-02-03';

    // Load country boundaries
    const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
    const cambodia = countries.filter(ee.Filter.eq('country_na', 'Cambodia'));
    const laos = countries.filter(ee.Filter.eq('country_na', 'Lao People\'s Democratic Republic'));

    // 2. Load MODIS Active Fires for the specific date
    const fires = ee.ImageCollection('MODIS/006/MCD14DL')
        .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'));

    // Check if collection is empty
    const fireCount = fires.size().getInfo();
    console.log(`Fire detections collection size: ${fireCount}`);

    if (fireCount === 0) {
        console.log("No fire detection data for this date.");
        console.log("<answer>C1</answer>");
        return;
    }

    // Get the single day's image
    const fireImage = fires.first();

    // Create fire mask: confidence > 0 means fire detection
    const fireMask = fireImage.select('Confidence').gt(0);

    // 3. Count fire pixels in each country
    const scale = 1000; // MODIS resolution is ~1km

    const cambodiaResult = fireMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: cambodia,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
    });

    const laosResult = fireMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: laos,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
    });

    const cambodiaFires = cambodiaResult.get('Confidence').getInfo();
    const laosFires = laosResult.get('Confidence').getInfo();

    console.log(`Cambodia fire detections: ${cambodiaFires}`);
    console.log(`Laos fire detections: ${laosFires}`);

    // 4. Validation and comparison
    if (cambodiaFires === null || laosFires === null) {
        console.log("Calculation returned null.");
        console.log("<answer>C3</answer>");
    } else if (typeof cambodiaFires !== 'number' || typeof laosFires !== 'number') {
        console.log("Invalid calculation result.");
        console.log("<answer>C3</answer>");
    } else if (cambodiaFires === 0 && laosFires === 0) {
        console.log("No fire detections in either country.");
        console.log("<answer>B</answer>"); // Cambodia does NOT have more fires
    } else if (cambodiaFires > laosFires) {
        console.log("Cambodia has more fire detections than Laos.");
        console.log("<answer>A</answer>");
    } else {
        console.log("Cambodia does NOT have more fire detections than Laos.");
        console.log("<answer>B</answer>");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(console.error);
